WITH ArielRating AS (
SELECT overall_rating FROM "Player_Attributes" WHERE player_name = 'Ariel Borysiuk'),
PaulinRating AS (
SELECT overall_rating FROM "Player_Attributes" WHERE player_name = 'Paulin Puel')
SELECT
  CAST(
    (
      (
        (
          SELECT
            overall_rating
          FROM ArielRating
        ) - (
          SELECT
            overall_rating
          FROM PaulinRating
        )
      ) * 100
    ) / (
      (
        SELECT
          overall_rating
        FROM PaulinRating
      )
    )
  ) AS REAL;

